-- Production schema additions. Apply after 0001 in a transaction.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email VARCHAR(320) UNIQUE NOT NULL, password_hash VARCHAR(300) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'reviewer', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS auth_sessions (id SERIAL PRIMARY KEY, token_hash VARCHAR(128) UNIQUE NOT NULL, csrf_token VARCHAR(128) NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oauth_states (id SERIAL PRIMARY KEY, value VARCHAR(128) UNIQUE NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS google_credentials (id SERIAL PRIMARY KEY, user_id INTEGER UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, email VARCHAR(320) NOT NULL DEFAULT '', access_token TEXT NOT NULL, refresh_token TEXT NOT NULL DEFAULT '', expires_at TIMESTAMPTZ NOT NULL, scopes JSONB NOT NULL DEFAULT '[]'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workflow_runs (id SERIAL PRIMARY KEY, workflow VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'queued', counts JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leads (id SERIAL PRIMARY KEY, external_id VARCHAR(160) UNIQUE NOT NULL, first_name VARCHAR(80) NOT NULL, company VARCHAR(160) NOT NULL DEFAULT '', title VARCHAR(160) NOT NULL DEFAULT '', source VARCHAR(40) NOT NULL, post_url VARCHAR(500) NOT NULL, excerpt TEXT NOT NULL, fit_score DOUBLE PRECISION NOT NULL, intent_score DOUBLE PRECISION NOT NULL, total_score DOUBLE PRECISION NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'drafted', draft TEXT NOT NULL DEFAULT '', evidence JSONB NOT NULL DEFAULT '{}'::jsonb, skipped_until TIMESTAMPTZ NULL);
CREATE TABLE IF NOT EXISTS debriefs (id SERIAL PRIMARY KEY, event_id VARCHAR(160) UNIQUE NOT NULL, account VARCHAR(160) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'needs_review', stage VARCHAR(40) NOT NULL DEFAULT 'Discovery', summary TEXT NOT NULL, next_steps JSONB NOT NULL DEFAULT '[]'::jsonb, evidence JSONB NOT NULL DEFAULT '[]'::jsonb, draft TEXT NOT NULL DEFAULT '', reminder_date VARCHAR(30) NULL, source_type VARCHAR(40) NOT NULL DEFAULT 'pasted_notes');
CREATE TABLE IF NOT EXISTS audit_events (id SERIAL PRIMARY KEY, action VARCHAR(100) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id VARCHAR(100) NOT NULL, detail JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
